<section class="cif-panel"><h2>Checklist automático</h2><div class="cif-table-wrap cif-table-wrap--embedded"><table class="cif-table"><thead><tr><th>Verificação</th><th>Resultado</th><th>Detalhe</th></tr></thead><tbody><?php foreach($checks as $check): ?><tr><td><strong><?= esc_html($check['name']) ?></strong></td><td><span class="cif-badge <?= $check['level']==='ok'?'cif-badge--success':($check['level']==='error'?'cif-badge--danger':'') ?>"><?= $check['level']==='ok'?'OK':($check['level']==='info'?'INFORMAÇÃO':($check['level']==='warning'?'ATENÇÃO':'ERRO')) ?></span></td><td><?= esc_html($check['detail']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>

